#!/bin/sh
# Build the runtime: dn-tiny, the tracer (src/dn-tiny), with the two programs that
# test and measure it, dn-substtest and dn-census.  All three are static aarch64
# executables with no libc and no imports, so any C compiler that emits aarch64
# code will do: Termux's clang, gcc on an arm64 Linux, or a cross compiler.
#
# The shim, dn-lane.so, is not built here: it is linked against the prefix's own
# glibc, so build-prefix.sh compiles it inside the prefix.
#
# The rows of the policy table (which syscalls are caught, where their path
# arguments are) are generated by src/dn-tiny/gen_rows.py, so python3 is needed.
#
# Usage: scripts/build-runtime.sh [OUTDIR]     (default: build/)
#   CC   the compiler (default: clang, else gcc, else aarch64-linux-gnu-gcc)
set -eu
ROOT=$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)
SRC="$ROOT/src/dn-tiny"
OUT=${1:-$ROOT/build}
mkdir -p "$OUT"
OUT=$(CDPATH= cd -- "$OUT" && pwd)

if [ -z "${CC:-}" ]; then
  for c in clang gcc aarch64-linux-gnu-gcc; do
    if command -v "$c" >/dev/null 2>&1; then CC=$c; break; fi
  done
fi
[ -n "${CC:-}" ] && command -v "$CC" >/dev/null 2>&1 || { echo "build-runtime: no C compiler (set CC)" >&2; exit 1; }
case "$("$CC" -dumpmachine)" in
  aarch64-*) ;;
  *) echo "build-runtime: $CC targets $("$CC" -dumpmachine), not aarch64 (set CC to a cross compiler)" >&2; exit 1 ;;
esac
command -v python3 >/dev/null 2>&1 || { echo "build-runtime: python3 not found (it generates the policy rows)" >&2; exit 1; }

FLAGS="-O2 -Wall -Wextra -static -nostdlib -ffreestanding -fno-builtin -fno-stack-protector
 -fno-asynchronous-unwind-tables -fno-pie -Wl,-z,noexecstack"
# gcc would turn a copy loop into a call to memcpy, which does not exist here
if echo 'int x;' | "$CC" -fno-tree-loop-distribute-patterns -x c -c -o /dev/null - 2>/dev/null; then
  FLAGS="$FLAGS -fno-tree-loop-distribute-patterns"
fi
case "$("$CC" --version 2>/dev/null)" in
  *clang*) ;;
  *) FLAGS="$FLAGS -no-pie" ;;
esac

mkdir -p "$OUT/gen"
python3 "$SRC/gen_rows.py" "$OUT/gen/policy-rows.inc"
# shellcheck disable=SC2086
"$CC" $FLAGS -I"$SRC" -I"$OUT/gen" -o "$OUT/dn-tiny" \
  "$SRC/sys.c" "$SRC/monitor.c" "$SRC/trace.c" "$SRC/exec.c" "$SRC/policy.c"
# shellcheck disable=SC2086
# the LD_AUDIT module (the loader hook): freestanding and shared, no libc
# shellcheck disable=SC2086
"$CC" -O2 -Wall -Wextra -shared -nostdlib -ffreestanding -fno-builtin -fno-stack-protector \
  -fno-asynchronous-unwind-tables -fPIC -Wl,-z,noexecstack -o "$OUT/dn-ldhook.so" "$SRC/ldhook.c"
"$CC" $FLAGS -o "$OUT/dn-substtest" "$SRC/substtest.c"
# shellcheck disable=SC2086
"$CC" $FLAGS -o "$OUT/dn-census" "$SRC/census.c"

if command -v nm >/dev/null 2>&1; then
  n=$(nm -u "$OUT/dn-tiny" | wc -l)
  [ "$n" -eq 0 ] || { echo "build-runtime: dn-tiny imports $n symbols" >&2; exit 1; }
fi
echo "build-runtime: $OUT/dn-tiny ($("$CC" -dumpversion 2>/dev/null || echo "$CC"))"
